const updateEvalCase = `-- name: UpdateEvalCase :one
UPDATE eval_cases SET enabled = $2, expectation = $3, updated_at = now() WHERE id = $1 RETURNING id, agent_name, kind, input, project_id, source_run_id, source, expectation, enabled, created_by, created_at, updated_at
`

type UpdateEvalCaseParams struct {
	ID          uuid.UUID
	Enabled     bool
	Expectation string
}

func (q *Queries) UpdateEvalCase(ctx context.Context, arg UpdateEvalCaseParams) (EvalCase, error) {
	row := q.db.QueryRow(ctx, updateEvalCase, arg.ID, arg.Enabled, arg.Expectation)
	var i EvalCase
	err := row.Scan(
		&i.ID,
		&i.AgentName,
		&i.Kind,
		&i.Input,
		&i.ProjectID,
		&i.SourceRunID,
		&i.Source,
		&i.Expectation,
		&i.Enabled,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
